/* test_package/check_pc.c
 *
 * Verifies the pkg-config file generated by lxqt_create_pkgconfig_file(),
 * a CMake helper module shipped by lxqt2-build-tools. This exercises the
 * package's real functionality (R34): if the module did not run correctly,
 * the .pc file is missing or lacks the expected fields and the test fails.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int contains(const char *haystack, const char *needle) {
    return strstr(haystack, needle) != NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <generated.pc>\n", argv[0]);
        return 2;
    }

    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        fprintf(stderr, "FAIL: cannot open generated .pc file %s\n", argv[1]);
        return 1;
    }

    char buf[4096];
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);
    buf[n] = '\0';

    int ok = 1;
    if (!contains(buf, "Name: lxqt2-test")) {
        fprintf(stderr, "FAIL: .pc file missing 'Name: lxqt2-test'\n");
        ok = 0;
    }
    if (!contains(buf, "Version: 2.4.0")) {
        fprintf(stderr, "FAIL: .pc file missing 'Version: 2.4.0'\n");
        ok = 0;
    }
    if (!contains(buf, "prefix=")) {
        fprintf(stderr, "FAIL: .pc file missing 'prefix='\n");
        ok = 0;
    }
    if (!contains(buf, "-llxqt2-test")) {
        fprintf(stderr, "FAIL: .pc file missing '-llxqt2-test' libs\n");
        ok = 0;
    }

    if (!ok) {
        fprintf(stderr, "----- generated .pc content -----\n%s\n", buf);
        return 1;
    }
    printf("OK: lxqt2-build-tools lxqt_create_pkgconfig_file() works\n");
    return 0;
}
